mapper.select:
SELECT	COUNT(*)
FROM	UI_INTEREST_USERS A
WHERE	A.ADMIN_ID = #{adminId}

SELECT A.USER_SEQ AS userSeq, A.ADMIN_ID AS adminId, A.USER_TYPE AS userType, A.USER_NM AS userNm, A.USER_ID AS userId, A.COMMENT AS comment, GROUP_CONCAT( DISTINCT B.USER_EMAIL ORDER BY B.USER_EMAIL SEPARATOR ',') AS userEmail, GROUP_CONCAT( DISTINCT C.USER_IP ORDER BY C.USER_IP SEPARATOR ',') AS userIp FROM UI_INTEREST_USERS A LEFT JOIN UI_INTEREST_USER_EMAIL B ON A.USER_SEQ = B.USER_SEQ LEFT JOIN UI_INTEREST_USER_IP C ON A.USER_SEQ = C.USER_SEQ WHERE A.ADMIN_ID = #{adminId}
AND A.USER_TYPE = #{userType}
AND A.USER_ID LIKE CONCAT('%', #{searchStr}, '%')
AND A.USER_NM LIKE CONCAT('%', #{searchStr}, '%')
AND ( A.USER_ID LIKE CONCAT('%', #{searchStr}, '%') OR A.USER_NM LIKE CONCAT('%', #{searchStr}, '%') )
GROUP BY A.USER_SEQ, A.ADMIN_ID, A.USER_TYPE, A.USER_NM, A.USER_ID, A.COMMENT ORDER BY USER_NM

SELECT  COUNT(*) AS CNT
FROM	UI_INTEREST_USERS
WHERE	ADMIN_ID = #{adminId}

AND		USER_SEQ != #{userSeq}

AND		USER_ID = #{userId}

		SELECT	IFNULL(SUM(CNT),0) AS cnt, GROUP_CONCAT( DISTINCT USER_IP ORDER BY USER_IP SEPARATOR ',') AS userIp
		FROM	(
				SELECT COUNT(*) AS CNT, B.USER_IP
        		FROM UI_INTEREST_USERS A LEFT JOIN UI_INTEREST_USER_IP B ON A.USER_SEQ = B.USER_SEQ
				WHERE	FIND_IN_SET(USER_IP, #{userIp})
				AND		A.ADMIN_ID = #{adminId}

				AND		A.USER_SEQ != #{userSeq}

				GROUP BY USER_IP
				) AS RS

	SELECT	IFNULL(SUM(CNT),0) AS cnt, GROUP_CONCAT( DISTINCT USER_EMAIL ORDER BY USER_EMAIL SEPARATOR ',') AS userEmail
		FROM	(
				SELECT COUNT(*) AS CNT, B.USER_EMAIL
        		FROM UI_INTEREST_USERS A LEFT JOIN UI_INTEREST_USER_EMAIL B ON A.USER_SEQ = B.USER_SEQ
				WHERE	FIND_IN_SET(USER_EMAIL, #{userEmail})
				AND		A.ADMIN_ID = #{adminId}

				AND		A.USER_SEQ != #{userSeq}

				GROUP BY USER_EMAIL
				) AS RS

mapper.update:
UPDATE	UI_INTEREST_USERS
SET		USER_TYPE = #{userType},
		USER_ID = #{userId},
		USER_NM = #{userNm},
		COMMENT = #{comment}
WHERE	USER_SEQ = #{userSeq} AND ADMIN_ID = #{adminId}

UPDATE	UI_INTEREST_USER_IP
SET		USER_IP = #{userIp}
WHERE	USER_SEQ = #{userSeq}

UPDATE	UI_INTEREST_USER_EMAIL
SET		USER_EMAIL = #{userEmail}
WHERE	USER_SEQ = #{userSeq}
